"""零依赖人工客服工作台页面。"""


def agent_workspace_html() -> str:
    """返回按客服原型组织的单页工作台。"""
    return r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><link rel="icon" href="data:,">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>欧莱雅 AI 客服助手</title>
<style>
:root{--ink:#171416;--muted:#777074;--line:#e6e1e3;--wine:#913c59;--rose:#fbf2f5;--canvas:#f8f6f6;--ok:#386b50}
*{box-sizing:border-box}body{margin:0;height:100vh;overflow:hidden;color:var(--ink);background:var(--canvas);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}button,textarea{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.42}button:focus-visible,textarea:focus-visible{outline:3px solid #dab0bf;outline-offset:2px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
.shell{height:100vh;display:grid;grid-template-rows:58px minmax(0,1fr)}.topbar{display:flex;align-items:center;justify-content:space-between;padding:0 24px;background:#171416;color:#fff}.brand{display:flex;align-items:center;gap:11px;font-weight:650}.brand-mark{font:700 25px Georgia,serif}.brand small{font-weight:400;color:#bdb5b8}.demo{font-size:12px;color:#ddd5d8}
.workspace{min-height:0;display:grid;grid-template-columns:292px minmax(440px,1fr) 410px}.queue,.assistant{min-width:0;background:#fff}.queue{border-right:1px solid var(--line);display:flex;flex-direction:column}.queue-head{padding:20px 18px 13px;border-bottom:1px solid var(--line)}.title-row{display:flex;align-items:center;justify-content:space-between}.title-row h1,.assistant-head h2{margin:0;font-size:18px}.icon-button,.text-button{border:0;background:transparent;color:var(--muted)}.icon-button{font-size:20px}.tabs{display:grid;grid-template-columns:1fr 1fr;margin-top:15px;padding:3px;background:#f3f0f1;border-radius:5px}.tab{border:0;border-radius:4px;padding:7px;background:transparent;color:#70676b}.tab.active{background:#fff;color:var(--ink);box-shadow:0 1px 4px #2f20250e}.sort-note{margin:11px 0 0;color:#948c8f;font-size:11px}.event-list{list-style:none;margin:0;padding:8px;overflow:auto}.event-button{width:100%;padding:13px 12px;text-align:left;background:#fff;border:1px solid transparent;border-radius:5px;margin-bottom:4px}.event-button:hover{background:#faf7f8}.event-button.selected{background:var(--rose);border-color:#eed9e0}.event-top{display:flex;justify-content:space-between;gap:8px}.event-name{font-weight:650}.pill{flex:none;padding:2px 7px;border-radius:99px;font-size:10px;color:#7f304b;background:#f4e2e8}.pill.danger{color:#9c223f;background:#fbe7ec}.event-reason{margin-top:8px;font-weight:600}.event-meta{display:flex;justify-content:space-between;margin-top:7px;color:var(--muted);font-size:11px}.queue-empty{padding:34px 18px;text-align:center;color:var(--muted)}
.conversation{min-width:0;min-height:0;display:flex;flex-direction:column;background:#faf8f8}.conversation-head{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:17px 22px;background:#fff;border-bottom:1px solid var(--line)}.conversation-head h2{margin:0;font-size:18px}.conversation-head p{margin:3px 0 0;color:var(--muted);font-size:11px}.auto-off{flex:none;color:#8c3653;background:var(--rose);padding:6px 9px;border-radius:4px;font-size:11px}.transcript{min-height:0;flex:1;overflow:auto;padding:22px;display:flex;flex-direction:column;gap:13px}.notice{align-self:center;color:#91898c;font-size:11px}.bubble{max-width:76%;padding:10px 13px;border:1px solid var(--line);background:#fff;border-radius:4px;white-space:pre-wrap;overflow-wrap:anywhere}.bubble.user{align-self:flex-start}.bubble.agent{align-self:flex-end;background:#f8e9ee;border-color:#ecd3dc}.bubble.ai{align-self:flex-start;background:#f2eeee}.bubble-meta{margin-bottom:4px;color:#847b7e;font-size:10px}.empty{height:100%;display:grid;place-items:center;text-align:center;color:#978f92}.handoff-card{background:#fff;border:1px solid var(--line);padding:11px 13px}.handoff-card summary{cursor:pointer;font-weight:600}.handoff-card pre{white-space:pre-wrap;font:12px/1.6 inherit;margin:9px 0 0}.composer{padding:14px 18px 16px;background:#fff;border-top:1px solid var(--line)}.composer-label{display:flex;justify-content:space-between;margin-bottom:7px;font-size:12px;font-weight:650}.composer-label button{border:0;background:transparent;color:var(--wine);font-size:11px}.composer-row{display:flex;align-items:flex-end;gap:9px}.composer textarea{flex:1;min-height:70px;resize:none;padding:11px;border:1px solid var(--line);border-radius:4px}.primary{border:0;background:var(--wine);color:#fff;border-radius:4px;padding:10px 16px}
.assistant{border-left:1px solid var(--line);overflow:auto}.assistant-head{position:sticky;top:0;z-index:2;display:flex;align-items:center;justify-content:space-between;padding:20px 18px 14px;background:#fff;border-bottom:1px solid var(--line)}.assistant-head .text-button{color:var(--wine)}.assist-section{padding:15px 18px;border-bottom:1px solid var(--line)}.assist-section h3{margin:0 0 9px;font-size:13px}.assist-section p,.assist-section pre{margin:0;white-space:pre-wrap;font:12px/1.65 inherit;color:#554d50}.section-link{border:0;background:transparent;color:var(--wine);padding:6px 0 0;font-size:11px}.callout{padding:11px 12px;background:var(--rose);border-left:3px solid #d69aad;color:#563e47}.risk-line{display:flex;justify-content:space-between;gap:10px}.risk-value{color:#8e2949;font-weight:650}.draft{padding:12px;background:var(--rose);color:#442f37!important}.feedback{display:flex;gap:8px;margin-top:10px}.feedback button{border:1px solid #d9cfd2;background:#fff;border-radius:4px;padding:7px 10px;color:#54494d}.feedback .adopt{border-color:var(--wine);background:var(--wine);color:#fff}.action-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:11px}.action-grid button{border:1px solid var(--line);background:#fff;border-radius:4px;padding:8px}.action-grid .danger{color:#96314f;background:#fff7f9}.sync{padding:13px 18px;color:#847b7e;font-size:11px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#4da26a;margin-right:5px}
@media(max-width:1080px){.workspace{grid-template-columns:260px minmax(420px,1fr)}.assistant{position:fixed;right:0;top:58px;bottom:0;width:390px;box-shadow:-8px 0 24px #291b2020}.assistant:not(.open){display:none}}@media(max-width:720px){body{overflow:auto}.shell{height:auto;min-height:100vh}.workspace{display:block}.queue{max-height:300px}.conversation{min-height:700px}.assistant{position:static;width:auto}.assistant:not(.open){display:block}}
</style></head><body><main class="shell"><header class="topbar"><div class="brand"><span class="brand-mark">L</span><span>欧莱雅 AI 客服助手</span><small>人工客服工作台</small></div><div class="demo">比赛演示 · 客服在线</div></header>
<section class="workspace"><aside class="queue"><div class="queue-head"><div class="title-row"><h1>会话队列</h1><button class="icon-button" onclick="load()" aria-label="刷新队列">↻</button></div><div class="tabs" role="tablist"><button id="processingTab" class="tab active" onclick="setQueueFilter('processing')">处理中 <span id="processingCount">0</span></button><button id="unclaimedTab" class="tab" onclick="setQueueFilter('unclaimed')">待认领 <span id="unclaimedCount">0</span></button></div><p class="sort-note">风险优先 · 同级按等待时长</p></div><ol id="events" class="event-list" aria-live="polite"></ol></aside>
<section class="conversation"><header class="conversation-head"><div><h2 id="caseTitle">选择一个消费者会话</h2><p id="caseMeta">处理模式与接管原因会显示在这里</p></div><span id="caseStatus" class="auto-off">AI自动发送已停用</span></header><div id="detail" class="transcript" aria-live="polite"><div class="empty">从左侧队列选择会话<br>查看顾客与 AI 已沟通的完整内容</div></div><section class="composer"><div class="composer-label"><label for="note">回复顾客</label><button onclick="document.getElementById('draftSection').scrollIntoView()">查看AI自动回复</button></div><div class="composer-row"><textarea id="note" rows="2" placeholder="输入回复，或采用右侧AI建议"></textarea><button id="reply" class="primary" onclick="action('reply')" disabled>发送回复</button></div></section></section>
<aside id="assistant" class="assistant open"><header class="assistant-head"><h2>会话助手</h2><button id="refreshDetail" class="text-button" onclick="refreshSelected()" disabled>重新分析</button></header><div class="assist-section"><h3>① 服务轨迹 · 已知进展</h3><pre id="knownProgress">选择会话后显示已确认的服务经过</pre><button class="section-link" onclick="toggleTimeline()">查看服务经过</button><pre id="timeline" hidden></pre></div><div class="assist-section"><h3>② 共情理解 · 还需核实</h3><div id="verifyNeeded" class="callout">尚未选择会话</div></div><div class="assist-section"><h3>④ 风险跟踪</h3><div class="risk-line"><span id="riskSummary">待判断</span><span id="riskLevel" class="risk-value">—</span></div><button class="section-link" onclick="toggleEvidence()">查看判断依据</button><pre id="evidence" hidden></pre></div><div class="assist-section"><h3>③ AI 建议 · 下一步</h3><pre id="nextStep">选择会话后显示建议动作</pre><div id="currentTodo" class="callout" style="margin-top:10px">当前任务：等待选择会话</div><button class="section-link" onclick="toggleEvidence()">查看依据</button></div><div id="draftSection" class="assist-section"><h3>可以这样回复</h3><p style="margin-bottom:7px;color:var(--muted)">草稿 · 发送前请人工确认</p><p id="assistantDraft" class="draft">暂无建议回复</p><div class="feedback" aria-label="AI 建议反馈"><button id="adoptSuggestion" class="adopt" onclick="suggestionFeedback('adopted')" disabled>采用到回复框</button><button id="editSuggestion" onclick="suggestionFeedback('edited')" disabled>记录修改</button><button id="rejectSuggestion" onclick="suggestionFeedback('rejected')" disabled>拒绝</button></div></div><div class="assist-section"><h3>人工处理</h3><p id="manualReason">AI 已停止自动发送，所有建议需人工确认。</p><div class="action-grid"><button id="complete" onclick="ticket('action_completed')" disabled>标记动作完成</button><button id="closeConversation" class="danger" onclick="closeConversation()" disabled>关闭会话</button></div></div><p id="syncStatus" class="sync"><span class="dot"></span>队列每 3 秒自动同步</p></aside></section></main>
<span class="sr-only">服务轨迹 共情理解 AI 建议 风险跟踪</span>
<script>
const eventsList=document.getElementById('events'),processingCount=document.getElementById('processingCount'),unclaimedCount=document.getElementById('unclaimedCount'),processingTab=document.getElementById('processingTab'),unclaimedTab=document.getElementById('unclaimedTab'),detailPanel=document.getElementById('detail'),caseTitleEl=document.getElementById('caseTitle'),caseMetaEl=document.getElementById('caseMeta'),caseStatusEl=document.getElementById('caseStatus'),replyButton=document.getElementById('reply'),completeButton=document.getElementById('complete'),refreshDetailButton=document.getElementById('refreshDetail'),noteInput=document.getElementById('note'),closeConversationButton=document.getElementById('closeConversation'),knownProgress=document.getElementById('knownProgress'),timeline=document.getElementById('timeline'),verifyNeeded=document.getElementById('verifyNeeded'),riskLevel=document.getElementById('riskLevel'),riskSummary=document.getElementById('riskSummary'),evidence=document.getElementById('evidence'),nextStep=document.getElementById('nextStep'),currentTodo=document.getElementById('currentTodo'),assistantDraft=document.getElementById('assistantDraft'),manualReason=document.getElementById('manualReason'),suggestionButtons=['adoptSuggestion','editSuggestion','rejectSuggestion'].map(x=>document.getElementById(x)),syncStatus=document.getElementById('syncStatus');
let selected=null,loading=false,selectedBrief=null,allEvents=[],queueFilter='processing';
async function call(path,options){const r=await fetch(path,options),b=r.status===204?{}:await r.json();if(!r.ok)throw new Error(b.detail||`HTTP ${r.status}`);return b}
function showAgentError(error){syncStatus.textContent=`同步失败：${error.message||error}`;syncStatus.style.color='#a51f48'}
function localTime(value){const normalized=/[zZ]|[+-][0-9][0-9]:[0-9][0-9]$/.test(value)?value:`${value}Z`;return new Date(normalized).toLocaleString()}
function statusLabel(value){return {waiting_for_agent:'等待客服',processing:'处理中',agent_replied:'已回复',action_completed:'处理完成',resolved:'消费者已确认',reopened:'再次处理中',completed:'已关闭'}[value]||value}
function enumLabel(value){return {neutral:'平静',anxious:'焦虑',angry:'愤怒',frustrated:'沮丧',positive:'积极',negative:'消极',low:'低',medium:'中',high:'高',consult:'咨询',purchase:'购买咨询',usage:'使用咨询',after_sales:'售后',complaint:'投诉',other:'其他',risk_specialist:'风险专员',logistics:'物流专员',open:'待处理',monitoring:'监控中',escalated:'已升级',closed:'已关闭',GUIDE:'引导处理',RESOLVE:'直接解决',ASK:'补充信息',HANDOFF:'转人工',BLOCK:'安全阻断',proposed:'待执行',executed:'已执行',skipped:'已跳过'}[value]||value}
function setQueueFilter(value){queueFilter=value;processingTab.classList.toggle('active',value==='processing');unclaimedTab.classList.toggle('active',value==='unclaimed');renderQueue()}
function renderQueue(){eventsList.replaceChildren();const visible=allEvents.filter(x=>queueFilter==='unclaimed'?x.status==='waiting_for_agent':x.status!=='waiting_for_agent');visible.forEach((x,index)=>{const li=document.createElement('li'),button=document.createElement('button');button.className='event-button'+(selected?.event_id===x.event_id?' selected':'');const top=document.createElement('div');top.className='event-top';const name=document.createElement('span');name.className='event-name';name.textContent=`顾客 ${String(index+1).padStart(2,'0')}`;const pill=document.createElement('span');pill.className='pill'+(x.priority>=100?' danger':'');pill.textContent=x.priority>=100?'必须人工':'AI辅助';top.append(name,pill);const reason=document.createElement('div');reason.className='event-reason';reason.textContent=x.reason.length>24?`${x.reason.slice(0,24)}…`:x.reason;const meta=document.createElement('div');meta.className='event-meta';meta.innerHTML=`<span>${statusLabel(x.status)}</span><span>${localTime(x.created_at)}</span>`;button.append(top,reason,meta);button.onclick=()=>selectEvent(x);li.append(button);eventsList.append(li)});if(!visible.length){const empty=document.createElement('li');empty.className='queue-empty';empty.textContent=queueFilter==='unclaimed'?'当前没有待认领会话':'当前没有处理中会话';eventsList.append(empty)}}
async function load(){if(loading)return;loading=true;try{const b=await call('/v1/agent/events');allEvents=b;processingCount.textContent=b.filter(x=>x.status!=='waiting_for_agent').length;unclaimedCount.textContent=b.filter(x=>x.status==='waiting_for_agent').length;if(!selected&&b.length&&b.every(x=>x.status==='waiting_for_agent'))setQueueFilter('unclaimed');else renderQueue();syncStatus.innerHTML='<span class="dot"></span>队列已同步 · '+new Date().toLocaleTimeString();syncStatus.style.color='';if(!selected&&b.length)await selectEvent(b[0],false);else if(selected&&b.some(x=>x.event_id===selected.event_id))await selectEvent(selected,false)}catch(e){showAgentError(e)}finally{loading=false}}
function toggleTimeline(){timeline.hidden=!timeline.hidden}function toggleEvidence(){evidence.hidden=!evidence.hidden}
async function selectEvent(event,reload=true){const preserveScroll=!reload&&selected?.event_id===event.event_id&&!detailPanel.querySelector('.empty'),previousScrollTop=detailPanel.scrollTop;selected=event;const b=await call(`/v1/agent/conversations/${event.conversation_id}`),p=b.handoff_package,brief=b.assistant_brief,empathy=b.agent_empathy_card;selectedBrief=brief;const attempts=p.attempts.length?p.attempts.map((x,i)=>`${i+1}. ${x.recommendation}｜${enumLabel(x.execution_status)}｜${x.observation||'无观察记录'}`).join('\n'):'暂无建议执行记录';
detailPanel.replaceChildren();const notice=document.createElement('div');notice.className='notice';notice.textContent=brief?'AI 辅助已就绪 · 自动发送已停用':`AI 已交接 · ${p.handoff_reason}`;detailPanel.append(notice);p.transcript.forEach(x=>{const bubble=document.createElement('div');bubble.className=`bubble ${x.role}`;const meta=document.createElement('div');meta.className='bubble-meta';meta.textContent=`${x.role==='user'?'顾客':x.role==='agent'?'人工客服':'AI 顾问'} · ${localTime(x.created_at)}`;const content=document.createElement('div');content.textContent=x.content;bubble.append(meta,content);detailPanel.append(bubble)});const card=document.createElement('details');card.className='handoff-card';const summary=document.createElement('summary');summary.textContent='查看 AI 交接摘要与处理建议';const info=document.createElement('pre');info.textContent=`状态：${enumLabel(p.current_state)}\n已确认事实：${p.confirmed_facts.join('\n')||'暂无'}\n仍缺信息：${p.missing_information.join('\n')||'暂无'}\n建议执行情况：${attempts}\n建议下一步：${p.suggested_next_step}`;card.append(summary,info);detailPanel.append(card);detailPanel.scrollTop=preserveScroll?previousScrollTop:detailPanel.scrollHeight;
const timelineText=brief?.service_timeline.map(x=>`${localTime(x.occurred_at)} · ${x.title}\n${x.detail}`).join('\n\n')||'暂无服务轨迹',evidenceText=brief?.evidence.map(x=>`${x.source}：${x.excerpt}`).join('\n')||'暂无可引用依据';knownProgress.textContent=`当前诉求：${empathy.current_request}\n已知信息：${empathy.known_information.join('；')||'暂无'}\n历史承诺：${empathy.historical_promises.join('；')||'暂无'}\n未完成事项：${empathy.unresolved_items.join('；')||'暂无'}`;timeline.textContent=timelineText;verifyNeeded.textContent=`消费者原话：${empathy.consumer_quote}\n当前情绪：${enumLabel(empathy.emotion)} · 紧迫度：${brief?enumLabel(brief.urgency):'待判断'}\n还需核实：${empathy.missing_information.join('；')||'暂无'}`;riskLevel.textContent=enumLabel(empathy.risk_level);riskSummary.textContent=`风险等级：${enumLabel(empathy.risk_level)}\n${empathy.risk_reasons.join('；')||'未发现明确风险'}`;evidence.textContent=evidenceText;nextStep.textContent=empathy.recommended_actions.join('\n')||p.suggested_next_step||'暂无';currentTodo.textContent=`当前任务：${empathy.unresolved_items[0]||p.suggested_next_step||'确认本次处理结果'}`;assistantDraft.textContent=brief?.reply_draft||'暂无建议回复';manualReason.textContent=`处理模式：${brief?'AI辅助':'人工接管'} · 原因：${p.handoff_reason}`;if(brief&&!noteInput.value.trim())noteInput.value=brief.reply_draft;
caseTitleEl.textContent=`顾客 · ${p.summary.length>24?`${p.summary.slice(0,24)}…`:p.summary}`;caseMetaEl.textContent=`处理模式：${brief?'AI辅助':'人工接管'} · 会话 ${p.conversation_id}`;caseStatusEl.textContent='AI自动发送已停用';[replyButton,completeButton,refreshDetailButton,closeConversationButton].forEach(x=>x.disabled=false);suggestionButtons.forEach(x=>x.disabled=!brief);renderQueue();if(reload)await load()}
async function refreshSelected(){if(selected)await selectEvent(selected)}
async function suggestionFeedback(decision){if(!selected||!selectedBrief)return;let payload={decision};if(decision==='adopted')noteInput.value=selectedBrief.reply_draft;if(decision==='edited'){if(!noteInput.value.trim()){showAgentError(new Error('请先修改回复草稿'));noteInput.focus();return}payload.final_reply=noteInput.value.trim()}if(decision==='rejected'){const reason=prompt('请填写拒绝 AI 建议的原因');if(!reason?.trim())return;payload.reason=reason.trim();noteInput.value=''}try{suggestionButtons.forEach(x=>x.disabled=true);await call(`/v1/agent/conversations/${selected.conversation_id}/suggestion-feedback`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});syncStatus.textContent=`已记录：${{adopted:'采纳',edited:'修改',rejected:'拒绝'}[decision]} AI 建议`;syncStatus.style.color=''}catch(e){showAgentError(e)}finally{suggestionButtons.forEach(x=>x.disabled=false)}}
async function action(name){if(name==='reply'&&!noteInput.value.trim()){noteInput.focus();showAgentError(new Error('请输入回复内容'));return false}const button=name==='reply'?replyButton:closeConversationButton;button.disabled=true;const originalLabel=button.textContent;button.textContent=name==='reply'?'发送中…':'关闭中…';try{await call(`/v1/agent/events/${selected.event_id}/actions`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:name,parameters:{note:noteInput.value}})});if(name==='reply')noteInput.value='';await load();return true}catch(e){showAgentError(e);return false}finally{button.textContent=originalLabel;if(selected)button.disabled=false}}
async function closeConversation(){if(!selected||!confirm('确认本次人工处理已完成并关闭会话？'))return;try{if(!await action('close'))return;selected=null;caseTitleEl.textContent='选择一个消费者会话';caseMetaEl.textContent='已关闭的会话已从待处理队列移除';caseStatusEl.textContent='已关闭';detailPanel.innerHTML='<div class="empty">会话已关闭<br>可继续处理左侧其他会话</div>';[replyButton,completeButton,refreshDetailButton,closeConversationButton].forEach(x=>x.disabled=true);await load()}catch(e){showAgentError(e)}}
async function ticket(event){if(!selected)return;try{await call(`/v1/agent/conversations/${selected.conversation_id}/ticket/results`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({event,note:noteInput.value})});syncStatus.textContent='已标记本次处理动作完成';await load()}catch(e){showAgentError(e)}}
noteInput.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();if(!replyButton.disabled)action('reply')}});load();setInterval(load,3000);
</script></body></html>"""
